/// <summary>
/// N.Freidenberger 02.06.2025
/// </summary>
public void insert()
{
    if (this.ReportFormat == 0)
    {
        PrintMgmtDocInstance        printMgmtDocInstance; 
        PrintMgmtReportFormat       printMgmtReportFormat;

        select firstonly printMgmtDocInstance
            where printMgmtDocInstance.RecId == this.ParentId;

        if (printMgmtDocInstance)
        {
            PrintMgmtReportFormatName formatName = PrintMgmtDocType::construct(printMgmtDocInstance.DocumentType).getDefaultReportFormat();

            select firstonly printMgmtReportFormat
                where printMgmtReportFormat.Name == formatName
                && printMgmtReportFormat.System;

            this.ReportFormat = printMgmtReportFormat.RecId;

        }

    }
    next insert();
}
